{"html":"<div class="page" id="page">
  <div class="card">
    <h1 class="title">다크모드 설정</h1>
    <p class="desc">버튼을 눌러 테마를 바꾸고, 새로고침해도 유지되게 만들어 보세요.</p>
    <button class="btn" id="themeBtn">다크모드로 전환</button>
  </div>
</div>","css":"body {
  margin: 0;
}

.page {
  min-height: 100vh;
  background: #f0f2f5;
  padding: 40px;
  transition: background 0.3s, color 0.3s;
}

.page.dark {
  background: #1a1a2e;
  color: white;
}

.card {
  background: white;
  padding: 32px;
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
  max-width: 400px;
}

.page.dark .card {
  background: #16213e;
  color: white;
}

.title {
  font-size: 22px;
  margin: 0 0 12px 0;
}

.desc {
  color: #666;
  font-size: 14px;
  line-height: 1.7;
  margin-bottom: 24px;
}

.page.dark .desc {
  color: #aaa;
}

.btn {
  background: #ff6b35;
  color: white;
  border: none;
  padding: 10px 24px;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
  font-family: inherit;
  font-weight: 600;
}","js":"// 버튼을 클릭하면 다크모드와 라이트모드를 전환하고
// localStorage에 현재 테마를 저장해보세요.
// 페이지를 새로고침해도 마지막 설정이 유지되어야 합니다.

const page = document.querySelector("#page");
const btn = document.querySelector("#themeBtn");

// 저장된 테마 불러오기
const savedTheme = localStorage.getItem("theme");
if (savedTheme === "dark") {
  page.classList.add("dark");
}

// 버튼 클릭 시 전환
btn.addEventListener("click", function() {
  page.classList.toggle("dark");

  if (page.classList.contains("dark")) {
    localStorage.setItem("theme", "dark");
  } else {
    localStorage.setItem("theme", "light");
  }
});"}

